import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        private int read() {
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = in.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public boolean hasNextInt() {
            while (ptr < len || len > 0) {
                while (ptr < len && buffer[ptr] <= ' ') {
                    ptr++;
                }
                if (ptr < len) return true;
                ptr = 0;
                try {
                    len = in.read(buffer);
                } catch (IOException e) {
                    return false;
                }
            }
            return false;
        }

        public int nextInt() {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return 0;
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * sign;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        int[] x = new int[n + 1];
        int[] y = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            x[i] = sc.nextInt();
            y[i] = sc.nextInt();
        }

        int numEdges = n + (n * (n - 1)) / 2;
        long[] edges = new long[numEdges];
        int edgeCount = 0;

        // Arestas do Palácio para cada tenda (u = 0)
        for (int i = 1; i <= n; i++) {
            long dx = x[i];
            long dy = y[i];
            long dist = dx * dx + dy * dy;
            edges[edgeCount++] = (dist << 24) | ((long) 0 << 12) | (long) i;
        }

        // Arestas entre tendas (u >= 1)
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                long dx = x[i] - x[j];
                long dy = y[i] - y[j];
                long dist = dx * dx + dy * dy;
                edges[edgeCount++] = (dist << 24) | ((long) i << 12) | (long) j;
            }
        }

        Arrays.sort(edges);

        int[] dp = new int[n + 1];
        int ans = 0;

        int[] updateNode = new int[2 * n + 5];
        int[] updateVal = new int[2 * n + 5];

        int i = 0;
        while (i < numEdges) {
            long curDist = edges[i] >>> 24;
            int updatesCount = 0;

            // Processa todas as arestas com a mesma distância
            while (i < numEdges && (edges[i] >>> 24) == curDist) {
                long edge = edges[i];
                int u = (int) ((edge >>> 12) & 0xFFF);
                int v = (int) (edge & 0xFFF);

                if (u == 0) {
                    // Aresta vinda do Palácio
                    if (dp[v] + 1 > ans) {
                        ans = dp[v] + 1;
                    }
                } else {
                    // Aresta entre tendas
                    int candU = dp[v] + 1;
                    int candV = dp[u] + 1;

                    if (updatesCount + 2 >= updateNode.length) {
                        updateNode = Arrays.copyOf(updateNode, updateNode.length * 2);
                        updateVal = Arrays.copyOf(updateVal, updateVal.length * 2);
                    }

                    updateNode[updatesCount] = u;
                    updateVal[updatesCount] = candU;
                    updatesCount++;

                    updateNode[updatesCount] = v;
                    updateVal[updatesCount] = candV;
                    updatesCount++;
                }
                i++;
            }

            // Aplica as atualizações do lote de arestas entre tendas
            for (int k = 0; k < updatesCount; k++) {
                int node = updateNode[k];
                int val = updateVal[k];
                if (val > dp[node]) {
                    dp[node] = val;
                }
            }
        }

        System.out.println(ans);
    }
}
